def compute_order_amount(on_hand_inventory, pipeline_orders):
    L = len(pipeline_orders)
    base_mu = 114.7513527895791  # OPT_PARAM: {"initial": 114.7513527895791, "min": 90, "max": 120, "type": "float"}
    safety_k = 0.0  # OPT_PARAM: {"initial": 0.0, "min": 0.0, "max": 1.0, "type": "float"}
    max_order = 95.97231189190668  # OPT_PARAM: {"initial": 95.97231189190668, "min": 90, "max": 150, "type": "float"}
    ip = on_hand_inventory + sum(pipeline_orders)
    avg = sum(pipeline_orders) / L
    var = sum((q - avg) ** 2 for q in pipeline_orders) / L
    std = var ** 0.5
    base_stock = base_mu * (L + 1) + safety_k * std * (L + 1) ** 0.5
    uncapped = max(0.0, base_stock - ip)
    order_amount = min(uncapped, max_order)
    return order_amount

